const r = await tools.exec_command({cmd:"python - <<'PY'
import json, numpy as np
from model import positional_state, entropy_rate
rng=np.random.default_rng(0)
mn=1; bad=[]; mx=0
for i in range(500):
 e=dict(force_x=rng.uniform(-1.5,1.5),force_y=rng.uniform(-1.5,1.5),drag_ratio=10**rng.uniform(np.log10(.25),np.log10(8)),magnetic=rng.uniform(-5,5),temperature=rng.uniform(.8,1.4),contrast=rng.uniform(0,.65),wavenumber=int(rng.integers(1,4)),bath_contrast=rng.uniform(0,.35),switch_rate=rng.uniform(.2,2))
 try:
  t,g,d,jx,jy,dx=positional_state(e,1.1)
  q=entropy_rate(*(e[k] for k in ('force_x','force_y','drag_ratio','magnetic','temperature','contrast','wavenumber','bath_contrast','switch_rate')),1.1)
  mn=min(mn,d.min()); mx=max(mx,abs(q))
  if not np.isfinite(q) or d.min()<=0: bad.append((i,d.min(),q,e))
 except Exception as ex: bad.append((i,str(ex),e))
print('min',mn,'max',mx,'bad',len(bad))
if bad: print(bad[:2])
PY",workdir:"/app",yield_time_ms:30000,max_output_tokens:3000}); text(r.output);

